int a = 2000000000;
int b = 1000000000;
int sum;

// bool __builtin_add_overflow(T a, T b, T* result);
// Returns true on overflow. Stores result (wrapped) in *result.
bool overflowed = __builtin_add_overflow(a, b, &sum);

if (overflowed) {
    // Overflow occurred
    // Handle error or use larger type
} else {
    // Safe result in 'sum'
}

// Subtraction Check
int diff;
__builtin_sub_overflow(a, b, &diff);

// Multiplication Check
int prod;
__builtin_mul_overflow(a, b, &prod);

// Manual Check (Unsigned Addition)
unsigned int x, y;
if (x > UINT_MAX - y) {
    // Overflow detected
}
